class $$ShiftTableTableManager
    extends
        RootTableManager<
          _$AppDatabase,
          $ShiftTable,
          ShiftRow,
          $$ShiftTableFilterComposer,
          $$ShiftTableOrderingComposer,
          $$ShiftTableAnnotationComposer,
          $$ShiftTableCreateCompanionBuilder,
          $$ShiftTableUpdateCompanionBuilder,
          (ShiftRow, $$ShiftTableReferences),
          ShiftRow,
          PrefetchHooks Function({
            bool outletId,
            bool perangkatId,
            bool penggunaId,
            bool transaksiRefs,
            bool kasShiftRefs,
            bool pembayaranRefs,
            bool refundRefs,
          })
        > {
  $$ShiftTableTableManager(_$AppDatabase db, $ShiftTable table)
    : super(
        TableManagerState(
          db: db,
          table: table,
          createFilteringComposer: () =>
              $$ShiftTableFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $$ShiftTableOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $$ShiftTableAnnotationComposer($db: db, $table: table),
          updateCompanionCallback:
              ({
                Value<String> id = const Value.absent(),
                Value<String> tokoId = const Value.absent(),
                Value<String> outletId = const Value.absent(),
                Value<String?> perangkatId = const Value.absent(),
                Value<String> penggunaId = const Value.absent(),
                Value<int> dibukaPada = const Value.absent(),
                Value<int?> ditutupPada = const Value.absent(),
                Value<int> modalAwal = const Value.absent(),
                Value<int?> kasSeharusnya = const Value.absent(),
                Value<int?> kasAktual = const Value.absent(),
                Value<int?> selisih = const Value.absent(),
                Value<String?> catatan = const Value.absent(),
                Value<ShiftStatus> status = const Value.absent(),
                Value<int> createdAt = const Value.absent(),
                Value<int> updatedAt = const Value.absent(),
                Value<int?> deletedAt = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => ShiftCompanion(
                id: id,
                tokoId: tokoId,
                outletId: outletId,
                perangkatId: perangkatId,
                penggunaId: penggunaId,
                dibukaPada: dibukaPada,
                ditutupPada: ditutupPada,
                modalAwal: modalAwal,
                kasSeharusnya: kasSeharusnya,
                kasAktual: kasAktual,
                selisih: selisih,
                catatan: catatan,
                status: status,
                createdAt: createdAt,
                updatedAt: updatedAt,
                deletedAt: deletedAt,
                rowid: rowid,
              ),
          createCompanionCallback:
              ({
                required String id,
                required String tokoId,
                required String outletId,
                Value<String?> perangkatId = const Value.absent(),
                required String penggunaId,
                required int dibukaPada,
                Value<int?> ditutupPada = const Value.absent(),
                Value<int> modalAwal = const Value.absent(),
                Value<int?> kasSeharusnya = const Value.absent(),
                Value<int?> kasAktual = const Value.absent(),
                Value<int?> selisih = const Value.absent(),
                Value<String?> catatan = const Value.absent(),
                required ShiftStatus status,
                required int createdAt,
                required int updatedAt,
                Value<int?> deletedAt = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => ShiftCompanion.insert(
                id: id,
                tokoId: tokoId,
                outletId: outletId,
                perangkatId: perangkatId,
                penggunaId: penggunaId,
                dibukaPada: dibukaPada,
                ditutupPada: ditutupPada,
                modalAwal: modalAwal,
                kasSeharusnya: kasSeharusnya,
                kasAktual: kasAktual,
                selisih: selisih,
                catatan: catatan,
                status: status,
                createdAt: createdAt,
                updatedAt: updatedAt,
                deletedAt: deletedAt,
                rowid: rowid,
              ),
          withReferenceMapper: (p0) => p0
              .map(
                (e) => (
                  e.readTable<$ShiftTable, ShiftRow>(table),
                  $$ShiftTableReferences(db, table, e),
                ),
              )
              .toList(),
          prefetchHooksCallback:
              ({
                outletId = false,
                perangkatId = false,
                penggunaId = false,
                transaksiRefs = false,
                kasShiftRefs = false,
                pembayaranRefs = false,
                refundRefs = false,
              }) {
                return PrefetchHooks(
                  db: db,
                  explicitlyWatchedTables: [
                    if (transaksiRefs) db.transaksi,
                    if (kasShiftRefs) db.kasShift,
                    if (pembayaranRefs) db.pembayaran,
                    if (refundRefs) db.refund,
                  ],
                  addJoins:
                      <
                        T extends TableManagerState<
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic
                        >
                      >(state) {
                        if (outletId) {
                          state =
                              state.withJoin(
                                    currentTable: table,
                                    currentColumn: table.outletId,
                                    referencedTable: $$ShiftTableReferences
                                        ._outletIdTable(db),
                                    referencedColumn: $$ShiftTableReferences
                                        ._outletIdTable(db)
                                        .id,
                                  )
                                  as T;
                        }
                        if (perangkatId) {
                          state =
                              state.withJoin(
                                    currentTable: table,
                                    currentColumn: table.perangkatId,
                                    referencedTable: $$ShiftTableReferences
                                        ._perangkatIdTable(db),
                                    referencedColumn: $$ShiftTableReferences
                                        ._perangkatIdTable(db)
                                        .id,
                                  )
                                  as T;
                        }
                        if (penggunaId) {
                          state =
                              state.withJoin(
                                    currentTable: table,
                                    currentColumn: table.penggunaId,
                                    referencedTable: $$ShiftTableReferences
                                        ._penggunaIdTable(db),
                                    referencedColumn: $$ShiftTableReferences
                                        ._penggunaIdTable(db)
                                        .id,
                                  )
                                  as T;
                        }

                        return state;
                      },
                  getPrefetchedDataCallback: (items) async {
                    return [
                      if (transaksiRefs)
                        await $_getPrefetchedData<
                          ShiftRow,
                          $ShiftTable,
                          TransaksiRow
                        >(
                          currentTable: table,
                          referencedTable: $$ShiftTableReferences
                              ._transaksiRefsTable(db),
                          managerFromTypedResult: (p0) =>
                              $$ShiftTableReferences(
                                db,
                                table,
                                p0,
                              ).transaksiRefs,
                          referencedItemsForCurrentItem:
                              (item, referencedItems) => referencedItems.where(
                                (e) => e.shiftId == item.id,
                              ),
                          typedResults: items,
                        ),
                      if (kasShiftRefs)
                        await $_getPrefetchedData<
                          ShiftRow,
                          $ShiftTable,
                          KasShiftRow
                        >(
                          currentTable: table,
                          referencedTable: $$ShiftTableReferences
                              ._kasShiftRefsTable(db),
                          managerFromTypedResult: (p0) =>
                              $$ShiftTableReferences(
                                db,
                                table,
                                p0,
                              ).kasShiftRefs,
                          referencedItemsForCurrentItem:
                              (item, referencedItems) => referencedItems.where(
                                (e) => e.shiftId == item.id,
                              ),
                          typedResults: items,
                        ),
                      if (pembayaranRefs)
                        await $_getPrefetchedData<
                          ShiftRow,
                          $ShiftTable,
                          PembayaranRow
                        >(
                          currentTable: table,
                          referencedTable: $$ShiftTableReferences
                              ._pembayaranRefsTable(db),
                          managerFromTypedResult: (p0) =>
                              $$ShiftTableReferences(
                                db,
                                table,
                                p0,
                              ).pembayaranRefs,
                          referencedItemsForCurrentItem:
                              (item, referencedItems) => referencedItems.where(
                                (e) => e.shiftId == item.id,
                              ),
                          typedResults: items,
                        ),
                      if (refundRefs)
                        await $_getPrefetchedData<
                          ShiftRow,
                          $ShiftTable,
                          RefundRow
                        >(
                          currentTable: table,
                          referencedTable: $$ShiftTableReferences
                              ._refundRefsTable(db),
                          managerFromTypedResult: (p0) =>
                              $$ShiftTableReferences(db, table, p0).refundRefs,
                          referencedItemsForCurrentItem:
                              (item, referencedItems) => referencedItems.where(
                                (e) => e.shiftId == item.id,
                              ),
                          typedResults: items,
                        ),
                    ];
                  },
                );
              },
        ),
      );
}

